function dsaFrameTextureKey(sequenceId, frameIndex) {
    return `${sequenceId}:${frameIndex}`;
}

function pruneDsaFrameTextures(snapshot) {
    const retainedKeys = new Set(
        snapshot.sequences.flatMap(sequence =>
            sequence.frames.map(frame => frame.storageKey)
        )
    );
    for (const [storageKey, texture] of dsaSequenceFrameTextures) {
        if (retainedKeys.has(storageKey)) continue;
        texture.dispose();
        dsaSequenceFrameTextures.delete(storageKey);
    }
    const retainedSequenceIds = new Set(
        snapshot.sequences.map(sequence => sequence.id)
    );
    for (const sequenceId of dsaSequencePreviewUrls.keys()) {
        if (!retainedSequenceIds.has(sequenceId)) {
            dsaSequencePreviewUrls.delete(sequenceId);
        }
    }
}

function selectedDsaFrameTexture(snapshot) {
    if (
        snapshot.selectedSequenceId === null ||
        snapshot.selectedFrameIndex === null
    ) return null;
    return dsaSequenceFrameTextures.get(
        dsaFrameTextureKey(
            snapshot.selectedSequenceId,
            snapshot.selectedFrameIndex
        )
    ) || null;
}

function clearCompositeRoadmapTexture() {
    dsaCompositeRoadmapTexture?.dispose?.();
    dsaCompositeRoadmapTexture = null;
    dsaCompositeRoadmapKey = '';
}

function createDsaLumaTexture(redChannel, width, height, name = '') {
    const textureFormat = renderer.capabilities.isWebGL2
        ? THREE.RedFormat
        : THREE.LuminanceFormat;
    const texture = new THREE.DataTexture(
        redChannel,
        width,
        height,
        textureFormat,
        THREE.UnsignedByteType
    );
    texture.minFilter = THREE.LinearFilter;
    texture.magFilter = THREE.LinearFilter;
    texture.wrapS = THREE.ClampToEdgeWrapping;
    texture.wrapT = THREE.ClampToEdgeWrapping;
    texture.generateMipmaps = false;
    texture.flipY = false;
    texture.colorSpace = THREE.NoColorSpace;
    texture.name = name;
    texture.needsUpdate = true;
    return texture;
}

function createDsaRangeCompositeTexture(storageKeys, name) {
    const sourceTextures = storageKeys
        .map(storageKey => dsaSequenceFrameTextures.get(storageKey))
        .filter(Boolean);
    if (sourceTextures.length !== storageKeys.length || !sourceTextures.length) {
        return null;
    }
    const firstImage = sourceTextures[0].image;
    if (!firstImage?.data || !firstImage.width || !firstImage.height) return null;
    const redChannels = [];
    for (let textureIndex = 0; textureIndex < sourceTextures.length; textureIndex++) {
        const image = sourceTextures[textureIndex].image;
        if (
            !image?.data ||
            image.width !== firstImage.width ||
            image.height !== firstImage.height ||
            image.data.length !== firstImage.data.length
        ) return null;
        redChannels.push(image.data);
    }
    const composite = composeDsaFrameRangeRedChannels(redChannels);
    if (!composite) return null;
    return createDsaLumaTexture(
        composite,
        firstImage.width,
        firstImage.height,
        name
    );
}

function buildDsaRangeRoadmap(sequenceId, startFrameIndex, endFrameIndex) {
    const snapshot = dsaRoadmapState.getSnapshot();
    const sequence = snapshot.sequences.find(candidate =>
        candidate.id === Number(sequenceId)
    );
    if (!sequence?.complete || !sequence.frames.length) {
        const result = dsaRoadmapState.selectRoadmapRange(
            sequenceId,
            startFrameIndex,
            endFrameIndex
        );
        syncDsaRoadmapState();
        return result;
    }
    const requestedStart = Number(startFrameIndex);
    const requestedEnd = Number(endFrameIndex);
    if (!Number.isFinite(requestedStart) || !Number.isFinite(requestedEnd)) {
        const result = dsaRoadmapState.selectRoadmapRange(
            sequence.id,
            startFrameIndex,
            endFrameIndex
        );
        syncDsaRoadmapState();
        return result;
    }
    const lastIndex = sequence.frames.length - 1;
    const startIndex = Math.max(0, Math.min(
        lastIndex,
        Math.min(Math.round(requestedStart), Math.round(requestedEnd))
    ));
    const endIndex = Math.max(0, Math.min(
        lastIndex,
        Math.max(Math.round(requestedStart), Math.round(requestedEnd))
    ));
    const storageKeys = sequence.frames
        .slice(startIndex, endIndex + 1)
        .map(frame => frame.storageKey);
    const compositeKey = `${sequence.id}:${startIndex}:${endIndex}`;
    if (
        dsaCompositeRoadmapTexture &&
        dsaCompositeRoadmapKey === compositeKey
    ) {
        const result = dsaRoadmapState.selectRoadmapRange(
            sequence.id,
            startIndex,
            endIndex
        );
        syncDsaRoadmapState();
        return result;
    }
    const compositeTexture = createDsaRangeCompositeTexture(
        storageKeys,
        `dsa-roadmap-range-${compositeKey}`
    );
    if (!compositeTexture) {
        console.warn('Unable to build DSA range roadmap texture', {
            sequenceId: sequence.id,
            startIndex,
            endIndex
        });
        return { ok: false, reason: 'The selected DSA frame range is unavailable' };
    }
    const result = dsaRoadmapState.selectRoadmapRange(
        sequence.id,
        startIndex,
        endIndex
    );
    if (!result.ok) {
        compositeTexture.dispose();
        syncDsaRoadmapState();
        return result;
    }
    clearCompositeRoadmapTexture();
    dsaCompositeRoadmapTexture = compositeTexture;
    dsaCompositeRoadmapKey = compositeKey;
    syncDsaRoadmapState();
    return result;
}

function cineDsaFrameTexture(snapshot) {
    if (
        snapshot.cineSequenceId === null ||
        snapshot.cineFrameIndex === null
    ) return null;
    return dsaSequenceFrameTextures.get(
        dsaFrameTextureKey(
            snapshot.cineSequenceId,
            snapshot.cineFrameIndex
        )
    ) || null;
}

function createDsaPreviewDataUrl(texture, maxWidth = 176, maxHeight = 118) {
    const source = texture?.image;
    if (!source?.data || !source.width || !source.height) return '';
    const scale = Math.min(
        1,
        maxWidth / source.width,
        maxHeight / source.height
    );
    const width = Math.max(1, Math.round(source.width * scale));
    const height = Math.max(1, Math.round(source.height * scale));
    const previewCanvas = document.createElement('canvas');
    previewCanvas.width = width;
    previewCanvas.height = height;
    const context = previewCanvas.getContext('2d', { alpha: false });
    if (!context) return '';
    const image = context.createImageData(width, height);
    for (let y = 0; y < height; y++) {
        const sourceY = source.height - 1 - Math.min(
            source.height - 1,
            Math.floor((y + 0.5) * source.height / height)
        );
        for (let x = 0; x < width; x++) {
            const sourceX = Math.min(
                source.width - 1,
                Math.floor((x + 0.5) * source.width / width)
            );
            const luma = source.data[sourceX + sourceY * source.width];
            const offset = (x + y * width) * 4;
            image.data[offset] = luma;
            image.data[offset + 1] = luma;
            image.data[offset + 2] = luma;
            image.data[offset + 3] = 255;
        }
    }
    context.putImageData(image, 0, 0);
    return previewCanvas.toDataURL('image/jpeg', 0.82);
}

function syncDsaRoadmapState() {
    const snapshot = dsaRoadmapState.getSnapshot();
    pruneDsaFrameTextures(snapshot);
    const cineTexture = cineDsaFrameTexture(snapshot);
    const selectedRoadmapTexture = snapshot.roadmapCompositeActive &&
        dsaCompositeRoadmapTexture
        ? dsaCompositeRoadmapTexture
        : selectedDsaFrameTexture(snapshot);
    displayMaterial.uniforms.roadmapTexture.value =
        selectedRoadmapTexture || roadmapTarget.texture;
    displayMaterial.uniforms.cineTexture.value =
        cineTexture || roadmapTarget.texture;
    displayMaterial.uniforms.dsaEnabled.value = snapshot.dsaEnabled;
    displayMaterial.uniforms.dsaMaskValid.value = snapshot.maskValid;
    displayMaterial.uniforms.roadmapEnabled.value = snapshot.roadmapEnabled;
    displayMaterial.uniforms.roadmapValid.value = snapshot.roadmapValid;
    displayMaterial.uniforms.cineEnabled.value = cineTexture !== null;
    ui.updateDsaRoadmapState({
        ...snapshot,
        sequences: snapshot.sequences.map(sequence => ({
            ...sequence,
            previewUrl: dsaSequencePreviewUrls.get(sequence.id)?.url || '',
            previewKey:
                dsaSequencePreviewUrls.get(sequence.id)?.storageKey || ''
        }))
    });
    return snapshot;
}

