function prepareSimulationStep(dt) {
    // Advance input, integrate rod physics, collisions, and update medical monitors
    const controlled = isControlledAccess();
    const inputs = synchronizedInputs?.[activeAccessId] ?? sampleSynchronizedInputs();
    const sampledCommands = controlled ?
        (typeof crossoverAppBenchmark!=='undefined'?crossoverAppBenchmark?.commands(dt,{wire:guidewireTransport.progress,catheter:pigtailCatheter.progress}):null)||
        sampleCatheterAortaScenario() || sampleBrowserBenchmarkScenario() : null;
    const automatedCommands = sampledCommands ? Object.freeze({ ...sampledCommands }) : null;
    if (controlled) updateGuidewireType(inputs.wireType);
    const deliveryDevice=stentGraftSystem?.accesses[activeAccessId].device;
    if(deliveryDevice) {
        configureDeliveryCatheter(deliveryDevice,pigtailCatheter);
    } else if(controlled) {
        pigtailCatheter.setType(automatedCommands?.catheterType ?? inputs.catheterType);
        pigtailCatheter.setStiffnessScales({shaftStiffnessScale:catheterShaftStiffnessScale,tipStiffnessScale:catheterTipStiffnessScale});
        pigtailCatheter.deliveryExposureMm=0;
    }
    for(const sheath of endovascularWorld.sheaths)sheath.innerRadius=deliveryDevice?pigtailCatheter.deliveryRadiusMm+.2:INTRODUCER_SHEATH_INNER_RADIUS_MM;
    if(sharedInputCheckpoint) {
        sharedInputScalars={tailProgress,guidewireRotation,lastGuidewireAdvanceCommand,xpbdPortalInnerDriven};
        sharedInputCheckpoint.capture([wire.nodeStorage,guidewireTransport,guidewireTransport.performanceStats,
            xpbdWireBody,xpbdCatheterBody,pigtailCatheter,pigtailCatheter._sheathFeed ??= {},
            pigtailCatheter._kirchhoffMaterialOptions,pigtailCatheter._kirchhoffBoundaryOptions,
            xpbdContainment,xpbdExternalToolContact]);
    }
    const backgroundWithdrawal=inputs.automatic;
    const advance = controlled ? automatedCommands?.guidewireAdvance ?? inputs.advance : backgroundWithdrawal.guidewireAdvance;
    const guidewireRotationCommand = controlled ? inputs.rotation : 0;
    if (guidewireRotationCommand !== 0) {
        guidewireRotation += guidewireRotationCommand *
            GUIDEWIRE_ROTATION_SPEED * dt;
        guidewireRotation = Math.atan2(
            Math.sin(guidewireRotation),
            Math.cos(guidewireRotation)
        );
    }
    const stentMode=!!deliveryDevice || (controlled && inputs.catheterTool==='stentgraft');
    const stentGraftCommand=deliveryDevice ? {deviceId:deliveryDevice.id,
        advance:controlled ? inputs.catheterAdvance : backgroundWithdrawal.catheterAdvance,
        release:controlled ? inputs.release : null} : null;
    const catheterAdvance = stentMode ? 0 :
        controlled ? automatedCommands?.catheterAdvance ?? inputs.catheterAdvance : backgroundWithdrawal.catheterAdvance;
    const catheterRotation = controlled ? automatedCommands?.catheterRotation ?? inputs.catheterRotation : 0;
    advanceTailInput(advance, dt);
    const inserted = Math.max(0, tailProgress);
    const catheterRotationBefore = pigtailCatheter.rotation;
    if(deliveryDevice)stentGraftCommand.mechanicalPosition=prepareDeliveryMotion(deliveryDevice,pigtailCatheter,dt,stentGraftCommand.advance,inserted,stentGraftCommand.release);
    else pigtailCatheter.advance(catheterAdvance, dt, inserted);
    pigtailCatheter.rotate(catheterRotation, dt);
    if (compositeAppSystem) compositeStepCommands = {
        wire: {spinIncrement: guidewireRotationCommand * GUIDEWIRE_ROTATION_SPEED * dt},
        catheter: {spinIncrement: pigtailCatheter.rotation - catheterRotationBefore}
    };
    {
        // The shared RodState storage carries the previous XPBD pose and
        // velocity. GuidewireTransport only moves the sheath-constrained boundary
        // in this mode; XPBD transmits that displacement through the elastic
        // body and finds the new contact-constrained equilibrium.
        xpbdWireBody.syncFromRodState(wire, XPBD_WIRE_SYNC_OPTIONS);
        xpbdWireBody.setActiveRange(
            wholeAxisAppSystem ? guidewireTransport.firstProximalSupportNodeIndex() :
                Math.min(xpbdWireBody.count - 2, Math.max(0, guidewireTransport.firstInsertedNodeIndex() - 1)),
            xpbdWireBody.count - 1
        );
        // Handle rotation is a torsional material-frame boundary. It does not
        // rotate positions or the manufactured kappa_0 field in world space.
        applyGuidewireProximalOrientation();
        let wireWallCollisionStart = Math.max(
            0,
            guidewireTransport.firstLumenNodeIndex() - 1
        );
        xpbdWireBody.setSheathMaterialEndNode(wireWallCollisionStart);
        let wireWallCollisionEnd = xpbdWireBody.segmentCount - 1;
        pigtailCatheter.stepPhysics(dt);
        const catheterNodeCount = pigtailCatheter.syncXpbdBody(
            xpbdCatheterBody
        );
        if (compositeAppSystem?.diagnostics.initializations === 0) {
            alignCompositeAppInitialMaterialFrames({body:xpbdWireBody,epoch:compositeInitialEpoch});
            alignCompositeAppInitialMaterialFrames({body:xpbdCatheterBody,epoch:compositeInitialEpoch});
        }
        const firstContainedNode = Math.max(0, Math.ceil((guidewireLength - inserted) / segmentLength));
        const materialEndNode = Math.min(
            xpbdWireBody.count - 1,
            Math.floor((guidewireLength - inserted + pigtailCatheter.progress) / segmentLength)
        );
        // Material overlap identifies the segment crossing the moving distal
        // opening. The solver keeps that crossing under its portal constraint;
        // spatial capture below separately decides when it may be rendered as
        // fully inside the catheter.
        const lastContainedNode = materialEndNode;
        endovascularWorld.updateContainmentWindow(xpbdContainment, {
            enabled:
                inserted > 0 &&
                pigtailCatheter.progress > 0.5 &&
                catheterNodeCount >= 2 &&
                lastContainedNode >= firstContainedNode,
            outerStartNode: pigtailCatheter.physicsLumenStartNode,
            startNode: firstContainedNode,
            endNode: Math.max(firstContainedNode, lastContainedNode),
            innerArcOffset:
                firstContainedNode * segmentLength - guidewireLength + inserted -
                    (pigtailCatheter.physicsLumenOrigin ?? 0),
            containedLength: Math.min(pigtailCatheter.progress, inserted) -
                (pigtailCatheter.physicsLumenOrigin ?? 0),
            enforceDistalPortal: true
        });

        xpbdWireBody.nodeRadius.fill(GUIDEWIRE_RADIUS_MM);
        xpbdWireBody.maxFrameDisplacement =
            Infinity;
        xpbdWireBody.frameDisplacementStartNode = Math.max(
            xpbdWireBody.activeStart,
            xpbdContainment.endNode
        );

        // The catheter shields the contained guidewire from the vessel wall.
        // Applying vessel contact to both concentric tools gives the wall two
        // independent ways to move the same coupled span and makes containment
        // fight a non-physical force through the catheter. Only the crossing
        // segment and guidewire material distal to the catheter remain exposed.
        if (xpbdContainment.enabled) {
            // Material overlap still owns shielding/contact classification.
            // Spatial capture only decides which nodes are solved as fully
            // contained; treating the transition nodes as externally exposed
            // makes them collide with both catheter and vessel at once.
            // The catheter may only move the collision boundary distally. A
            // short catheter initially ends proximal to the sheath outlet;
            // replacing the sheath boundary with that material node would
            // expose guidewire that is physically still inside the introducer.
            const firstWallExposedSegment = Math.max(
                wireWallCollisionStart,
                materialEndNode
            );
            if (firstWallExposedSegment <= xpbdWireBody.activeEnd - 1) {
                wireWallCollisionStart = firstWallExposedSegment;
            } else {
                wireWallCollisionStart = xpbdWireBody.activeEnd;
                wireWallCollisionEnd = xpbdWireBody.activeEnd - 1;
            }
        }
        // Commit the final mask once. Toggling through the unshielded range and
        // back in one frame woke a stationary guidewire every step.
        xpbdWireBody.setCollisionRange(
            wireWallCollisionStart,
            wireWallCollisionEnd
        );

        const catheterEndSegment = Math.max(0, catheterNodeCount - 2);
        const firstExternalSegment = Math.max(0, Math.min(
            xpbdWireBody.segmentCount - 1,
            materialEndNode + 1
        ));
        // The portal constraint owns the crossing segment. External capsule
        // contact starts one segment farther distally, where the wire is fully
        // outside the catheter, so the opening remains free of a false cap.
        xpbdExternalToolContact.enabled =
            pigtailCatheter.progress > 4 &&
            catheterNodeCount >= 2 &&
            inserted > pigtailCatheter.progress + 0.5 &&
            firstExternalSegment <= xpbdWireBody.activeEnd - 1;
        xpbdExternalToolContact.startSegmentA = firstExternalSegment;
        xpbdExternalToolContact.endSegmentA = Math.min(
            xpbdWireBody.activeEnd - 1,
            firstExternalSegment + 16
        );
        xpbdExternalToolContact.startSegmentB = Math.max(xpbdCatheterBody.activeStart, catheterEndSegment - 8);
        xpbdExternalToolContact.endSegmentB = catheterEndSegment;

        // One numerical policy for both instruments in feed, hold, rotation
        // and withdrawal. Only their material/geometric profiles differ.
        configureKirchhoffToolRuntime(xpbdWireBody);
        configureKirchhoffToolRuntime(xpbdCatheterBody);
        return { dt, automatedCommands, inserted, firstContainedNode, materialEndNode, stentGraftCommand,
            benchmarkEpoch: browserBenchmarkEpoch,
            benchmarkRunning: controlled && browserBenchmarkScenario.running,
            benchmarkClockAdvances: controlled && browserBenchmarkScenario.running && !browserBenchmarkScenario.memorySettling };
    }
}

function stepSimulation(dt = fixedDt) {
    return simulationStepTransaction.attempt(dt);
}

function commitSimulationStep(context) {
    const { dt, firstContainedNode, materialEndNode } = context;
    const spatialRenderEnd = spatiallyCapturedContainmentEnd({
        innerBody: xpbdWireBody,
        outerBody: xpbdCatheterBody,
        firstContainedNode,
        materialEndNode,
        outerStartNode: xpbdContainment.outerStartNode,
        outerInnerRadius: xpbdContainment.innerRadius,
        closestSegment: xpbdContainment.closestSegment
    });
    xpbdContainment.renderEndNode = Math.min(
        materialEndNode,
        Math.max(
            firstContainedNode,
            materialEndNode - 1,
            spatialRenderEnd
        )
    );
    xpbdWireBody.syncToRodState(wire);
    stentGraftSystem?.updateAccess(activeAccessId,dt,{nodes:wire.nodes,
        coordinate:i=>guidewireTransport.insertedCoordinate(i),catheterMm:pigtailCatheter.type==='stentgraft-delivery'?0:pigtailCatheter.progress,
        deliveryBody:pigtailCatheter.type==='stentgraft-delivery'?xpbdCatheterBody:null},
        context.stentGraftCommand?{...context.stentGraftCommand,mechanicalRotation:pigtailCatheter.rotation}:null);
}

function presentSimulationStep(context) {
    const {dt, inserted, automatedCommands} = context;
    // Publish accepted lengths for both sheaths: a background withdrawal must
    // stop at the inlet without touching the foreground UI or trial state.
    ui.updateAutomaticWithdrawalLengths(activeAccessId,inserted/10,
        (stentGraftSystem?.accesses[activeAccessId].device?.position??pigtailCatheter.progress)/10);
    if (!isControlledAccess()) return;
    const sameBenchmark = context.benchmarkEpoch === browserBenchmarkEpoch &&
        context.benchmarkRunning && browserBenchmarkScenario.running;
    if (sameBenchmark) {
        if (context.benchmarkClockAdvances) browserBenchmarkScenario.simulationElapsedMs += dt * 1000;
        shortCatheterBenchmarkMetrics?.recordStep(automatedCommands?.benchmarkPhase ?? -1,
            endovascularWorld, inserted, pigtailCatheter.progress, simulationAccumulator);
        recordBrowserPhysicsEnvelope();
    }
    updateGuidewireResistance();
    ui.updateInsertedLength(inserted / 10, guidewireRotation);
    ui.updateCatheterLength(pigtailCatheter.progress / 10, pigtailCatheter.rotation);
    if (contrastSystem && Math.abs(contrastSystem.totalDeliveredVolumeMl - displayedContrastDoseMl) >= 0.01) {
        displayedContrastDoseMl = contrastSystem.totalDeliveredVolumeMl;
        ui.updateDose(displayedContrastDoseMl);
    }
}

const renderHiddenObjects = [];
function renderOnlySceneObject(scene, camera, object) {
    renderHiddenObjects.length = 0;
    for (const child of scene.children) {
        if (child.isCamera) continue;
        const shouldRender = (Array.isArray(object) ? object.includes(child) : child === object) && child.visible;
        if (!shouldRender && child.visible) {
            renderHiddenObjects.push(child);
            child.visible = false;
        }
    }
    renderer.render(scene, camera);
    for (let index = 0; index < renderHiddenObjects.length; index++) {
        renderHiddenObjects[index].visible = true;
    }
}

const depthHiddenObjects = [];
const depthHiddenVisibility = [];

function staticAnatomyProjectionChanged() {
    camera.updateMatrixWorld(true);
    const world = camera.matrixWorld.elements;
    const projection = camera.projectionMatrix.elements;
    let changed = !anatomyProjectionValid;
    for (let index = 0; index < 16 && !changed; index++) {
        changed = world[index] !== anatomyCameraWorld[index] ||
            projection[index] !== anatomyProjectionMatrix[index];
    }
    if (!changed) return false;
    anatomyCameraWorld.set(world);
    anatomyProjectionMatrix.set(projection);
    anatomyProjectionValid = true;
    return true;
}

function updateStaticAnatomyProjection() {
    depthHiddenObjects.length = 0;
    depthHiddenVisibility.length = 0;
    for (const child of scene.children) {
        if (child !== skeletonModel && !child.isCamera) {
            depthHiddenObjects.push(child);
            depthHiddenVisibility.push(child.visible);
            child.visible = false;
        }
    }
    scene.overrideMaterial = depthMaterialFront;
    renderer.setRenderTarget(frontDepthTarget);
    renderer.clear();
    renderer.render(scene, camera);
    scene.overrideMaterial = depthMaterialBack;
    renderer.setRenderTarget(backDepthTarget);
    renderer.clear();
    renderer.render(scene, camera);
    scene.overrideMaterial = null;
    renderer.setRenderTarget(null);
    for (let index = 0; index < depthHiddenObjects.length; index++) {
        depthHiddenObjects[index].visible = depthHiddenVisibility[index];
    }

    thicknessMaterial.uniforms.frontDepth.value = frontDepthTarget.texture;
    thicknessMaterial.uniforms.backDepth.value = backDepthTarget.texture;
    renderer.setRenderTarget(thicknessTarget);
    renderer.render(thicknessScene, postCamera);
    renderer.setRenderTarget(null);

    renderer.setRenderTarget(boneTarget);
    renderer.clear();
    scene.overrideMaterial = boneProjectionMaterial;
    renderOnlySceneObject(scene, camera, skeletonModel);
    scene.overrideMaterial = null;
    renderer.setRenderTarget(null);
}

function renderDisplayCapture(target, {
    dsaEnabled = false,
    dsaMaskValid = false
} = {}) {
    const uniforms = displayMaterial.uniforms;
    const previousDsaEnabled = uniforms.dsaEnabled.value;
    const previousDsaMaskValid = uniforms.dsaMaskValid.value;
    const previousRoadmapEnabled = uniforms.roadmapEnabled.value;
    const previousRoadmapValid = uniforms.roadmapValid.value;
    const previousCineEnabled = uniforms.cineEnabled.value;
    const previousDsaMaskTexture = uniforms.dsaMaskTexture.value;
    const previousRoadmapTexture = uniforms.roadmapTexture.value;
    const previousResolutionX = uniforms.resolution.value.x;
    const previousResolutionY = uniforms.resolution.value.y;

    uniforms.dsaEnabled.value = dsaEnabled;
    uniforms.dsaMaskValid.value = dsaMaskValid;
    uniforms.roadmapEnabled.value = false;
    uniforms.roadmapValid.value = false;
    uniforms.cineEnabled.value = false;
    uniforms.resolution.value.set(target.width, target.height);

    // Never bind a render target as a sampler while writing into it.
    if (target === dsaMaskTarget) {
        uniforms.dsaMaskTexture.value = roadmapTarget.texture;
    }
    if (target === roadmapTarget) {
        uniforms.roadmapTexture.value = dsaMaskTarget.texture;
    }

    renderer.setRenderTarget(target);
    renderer.clear();
    renderer.render(displayScene, postCamera);

    uniforms.dsaEnabled.value = previousDsaEnabled;
    uniforms.dsaMaskValid.value = previousDsaMaskValid;
    uniforms.roadmapEnabled.value = previousRoadmapEnabled;
    uniforms.roadmapValid.value = previousRoadmapValid;
    uniforms.cineEnabled.value = previousCineEnabled;
    uniforms.dsaMaskTexture.value = previousDsaMaskTexture;
    uniforms.roadmapTexture.value = previousRoadmapTexture;
    uniforms.resolution.value.set(previousResolutionX, previousResolutionY);
}

function createArchivedDsaFrame() {
    const width = dsaFrameCaptureTarget.width;
    const height = dsaFrameCaptureTarget.height;
    const requiredLength = width * height * 4;
    if (dsaFrameReadback.length !== requiredLength) {
        dsaFrameReadback = new Uint8Array(requiredLength);
    }
    renderer.readRenderTargetPixels(
        dsaFrameCaptureTarget,
        0,
        0,
        width,
        height,
        dsaFrameReadback
    );
    const redChannel = new Uint8Array(width * height);
    for (let index = 0; index < redChannel.length; index++) {
        redChannel[index] = dsaFrameReadback[index * 4];
    }
    return createDsaLumaTexture(
        redChannel,
        width,
        height,
        'dsa-archive-frame'
    );
}

function projectedContrastScore() {
    renderer.setRenderTarget(dsaContrastScoreTarget);
    renderer.setClearColor(0x000000, 0);
    renderer.clear();
    renderer.render(contrastScene, camera);
    renderer.setClearColor(0x000000, 1);
    const width = dsaContrastScoreTarget.width;
    const height = dsaContrastScoreTarget.height;
    const requiredLength = width * height * 4;
    if (dsaContrastScoreReadback.length !== requiredLength) {
        dsaContrastScoreReadback = new Uint8Array(requiredLength);
    }
    renderer.readRenderTargetPixels(
        dsaContrastScoreTarget,
        0,
        0,
        width,
        height,
        dsaContrastScoreReadback
    );
    return scoreProjectedContrastRgba(
        dsaContrastScoreReadback,
        width,
        height,
        activeCollimatorSettings()
    );
}

function dsaRecordingFrameDue() {
    return dsaRoadmapState.isRecordingFrameDue({
        frameIntervalMs: 1000 / Math.max(1, displayMaterial.uniforms.pulseRate.value || 15)
    });
}

function captureDsaSequenceFrame() {
    const contrastScore = projectedContrastScore();
    renderDisplayCapture(dsaFrameCaptureTarget, {
        dsaEnabled: true,
        dsaMaskValid: true
    });
    const archivedTexture = createArchivedDsaFrame();
    const appended = dsaRoadmapState.appendRecordingFrame({
        contrastScore,
        frameIntervalMs: 1000 / Math.max(1, displayMaterial.uniforms.pulseRate.value || 15),
        capturedAtMs: dsaRoadmapState.nowMs()
    });
    if (!appended.ok) {
        archivedTexture.dispose();
        return appended;
    }
    archivedTexture.name = `dsa-sequence-${appended.storageKey}`;
    dsaSequenceFrameTextures.set(appended.storageKey, archivedTexture);
    if (appended.isBest) {
        dsaSequencePreviewUrls.set(appended.sequenceId, {
            storageKey: appended.storageKey,
            url: createDsaPreviewDataUrl(archivedTexture)
        });
    }
    if (appended.shouldStop) {
        const finished = dsaRoadmapState.finishSequenceRecording({
            endedAtMs: dsaRoadmapState.nowMs()
        });
        if (finished.ok) clearCompositeRoadmapTexture();
    }
    return appended;
}

function processDsaRoadmapCapture() {
    const revision = ui.getCArmRevision();
    const nowMs = dsaRoadmapState.nowMs();
    let snapshot = dsaRoadmapState.getSnapshot();
    const contrastVisible = contrastSystem?.hasVisibleContrast?.() === true;
    let maskCapturedThisPulse = false;

    if (
        snapshot.maskCapturePending &&
        dsaRoadmapState.isMaskCaptureReady({ nowMs })
    ) {
        renderDisplayCapture(dsaMaskTarget, {
            dsaEnabled: false,
            dsaMaskValid: false
        });
        dsaRoadmapState.markMaskCaptured(revision, { nowMs });
        maskCapturedThisPulse = true;
        snapshot = syncDsaRoadmapState();
    }

    if (snapshot.roadmapCapturePending) {
        if (!contrastVisible) {
            dsaRoadmapState.failRoadmapCapture(
                'Contrast is no longer visible · inject before capturing roadmap'
            );
        } else {
            renderDisplayCapture(roadmapTarget, {
                dsaEnabled: true,
                dsaMaskValid: true
            });
            if (dsaRoadmapState.markRoadmapCaptured(revision)) {
                clearCompositeRoadmapTexture();
            }
        }
        snapshot = syncDsaRoadmapState();
    }

    if (
        snapshot.recording &&
        snapshot.maskValid &&
        !maskCapturedThisPulse &&
        dsaRecordingFrameDue()
    ) {
        captureDsaSequenceFrame();
        syncDsaRoadmapState();
    }
}

function executeAccessPhysicsStep(sliceBudgetMs = null) {
    // Attempt only this member; the common barrier owns time and publication.
    if (wholeAxisAppSystem && (!loadingAssetsReady() || !endovascularWorld.contactField)) return false;
    if (!simulationStepTransaction.canAttempt()) return false;
    if (simulationStepTransaction.blocked && synchronizedInputs)
        synchronizedInputs[activeAccessId] = sampleSynchronizedInputs();
    const startedAt = performance.now();
    let result;
    try {
        if(sharedAxisAppSystem&&sliceBudgetMs!==null)
            sharedAxisAppSystem.setWorkSliceBudget(sliceBudgetMs);
        result = stepSimulation(fixedDt);
        if(typeof crossoverAppBenchmark!=='undefined')crossoverAppBenchmark?.recordSlice(result.durationMs??0,result);
        crossoverScenario?.slice(result.durationMs??0,result);
        if(sharedAxisAppSystem) {
            // Sum synchronous work across every retry of this prepared dt.
            // This includes input preparation and native buffer publication,
            // but excludes the time waiting between cooperative slices.
            simulationPendingStepCpuMs+=result.durationMs??0;
            const sameBenchmark=isControlledAccess()&&browserBenchmarkScenario.running&&(!result.accepted||
                result.context?.benchmarkEpoch===browserBenchmarkEpoch&&result.context?.benchmarkRunning);
            if(sameBenchmark)browserConstraintStageProfile.record(endovascularWorld,
                result.accepted?{fullStepCpuMs:simulationPendingStepCpuMs}:{});
            if(sameBenchmark&&[WIRE60_BENCHMARK_MODE,FULL_CYCLE_BENCHMARK_MODE].includes(browserBenchmarkScenario.mode)&&(result.accepted||result.terminal)) {
                const last=endovascularWorld.lastStepResult?.diagnostics?.last;
                wire60StepSamples.push({accepted:result.accepted,status:result.status,
                    wire:guidewireTransport.progress,catheter:pigtailCatheter.progress,
                    wallMs:performance.now()-browserBenchmarkScenario.startedAt,simulationMs:browserBenchmarkScenario.simulationElapsedMs,
                    cpuMs:simulationPendingStepCpuMs,providerMs:last?.cpuMs,timings:last?.timings,
                    iterations:last?.iterations,factorizations:last?.factorizations,substepAttempts:last?.substepAttempts,
                    assemblies:(last?.fullAssemblies??0)+(last?.residualAssemblies??0),
                    nodes:sharedAxisAppSystem.diagnostics.mesh?.nodes,
                    frictionFallbacks:last?.coupledFrictionFallbacks,
                    geometryRestarts:last?.geometryRestarts,wallNormalFallbacks:last?.wallNormalFallbacks});
            }
            if(result.accepted)simulationPendingStepCpuMs=0;
        }
        simulationLastAttempt = { accepted: result.accepted, status: result.status,
            frame: simulationStepTransaction.frame, error: result.error?.message ?? null,
            firstError: result.firstError?.message ?? result.error?.message ?? null };
        if (result.error) console.error('Physical timestep failed; prepared input retained', result.firstError ?? result.error);
        if(result.terminal) {
            simulationPendingStepCpuMs=0;
            if (synchronizedInputs) synchronizedInputs[activeAccessId] = sampleSynchronizedInputs();
            if(isControlledAccess()&&browserBenchmarkScenario.running)stopBrowserBenchmarkScenario('terminal-physics-failure');
            // Export/presentation failure must never prevent terminal recovery.
            try {
                const failure=sharedAxisAppSystem?.getLastFailure();
                if(failure) {
                    console.warn('Shared-axis step rejected', failure.failure.result.status, failure.failure.result.error ?? '',
                        'Zapis do odtworzenia: Debug → Pobierz wszystkie');
                }
            } catch(error) { console.error('Could not present rejected-step capture', error); }
        }
        return result;
    } catch (error) {
        simulationStepTransaction.blockCurrentFrame();
        console.error('Simulation step failed', error);
        // Diagnostics execute after World may have irreversibly accepted dt.
        // Keep that acceptance at the barrier even if profiling/UI fails.
        if (result?.accepted) { simulationPendingStepCpuMs = 0; return result; }
        return {accepted:false, pending:false, error};
    } finally {
        const duration = performance.now() - startedAt;
        // Failed attempts cost CPU too; they do not consume simulated time.
        simulationStepEstimateMs = Math.max(duration, simulationStepEstimateMs * 0.8);
    }
}

synchronizedStep = createSynchronizedStep({
    members: accessController.values().map(access => ({
        canAttempt: () => accessController.run(access.activeAccessId, () => simulationStepTransaction.canAttempt()),
        beginFrame: () => accessController.run(access.activeAccessId, () => simulationStepTransaction.beginFrame()),
        attempt: (dt, budget) => accessController.run(access.activeAccessId, () => executeAccessPhysicsStep(budget))
    })),
    begin: () => {
        prepareBrowserBenchmarkBoundary();
        flushSimulationChanges();
        synchronizedInputs = Object.fromEntries(accessController.values().map(access =>
            [access.activeAccessId, accessController.run(access.activeAccessId, sampleSynchronizedInputs)]));
        if(crossoverScenario?.active)synchronizedInputs=crossoverScenario.boundary(synchronizedInputs,readCrossoverScenarioConfiguration());
    },
    publish: (dt, results) => {
        const crossoverPublicationStart=typeof crossoverAppBenchmark!=='undefined'&&crossoverAppBenchmark?performance.now():0;
        // No rendering or event handling can observe the intervening calls.
        for (let i = 0; i < results.length; i++) {
            const access = accessController.values()[i];
            accessController.run(access.activeAccessId, () => commitSimulationStep(results[i].context));
        }
        contrastSystem?.setStentGraftSurface(stentGraftSystem?.getContrastSurface(dt,
            contrastSystem.isInjecting || contrastSystem.hasVisibleContrast()));
        contrastSystem?.advanceSynchronized(dt);
        monitor.advance(dt);
        simulationAccumulator = Math.max(0, simulationAccumulator - dt);
        simulationExecutedSteps++;
        completedSimulationTime += dt;
        patientSoftTissue.update(completedSimulationTime, {
            respiratoryRate: monitor.respiratoryRate,
            cardiacPhase: monitor.ecgSamplesSinceBeat / monitor.ecgSamplesToNextBeat
        });
        synchronizedInputs = null;
        // Freeze presentation from the fully committed state before another
        // cooperative tick can mutate the underlying mechanical buffers.
        for (const [i, access] of accessController.values().entries()) accessController.run(access.activeAccessId, () => {
            try {
                presentSimulationStep(results[i].context);
                updateWireMesh();
                pigtailCatheter.updateMesh();
                access.rodNodes.update(xpbdWireBody, xpbdCatheterBody, !fluoroscopy && debugLayerVisibility.rodNodes);
                stentGraftSystem.refreshDelivery(activeAccessId);
            } catch (error) { console.error('Simulation presentation failed', error); }
        });
        if (contrastSystem) {
            displayedContrastDoseMl = contrastSystem.totalDeliveredVolumeMl;
            try { ui.updateDose(displayedContrastDoseMl); }
            catch (error) { console.error('Dose presentation failed', error); }
        }
        if(typeof crossoverAppBenchmark!=='undefined')crossoverAppBenchmark?.recordCommit(dt,sharedAxisAppSystem.diagnostics,performance.now()-crossoverPublicationStart);
        if(crossoverScenario?.active) {
            try {
                const state=sharedAxisAppSystem.captureFlowSamplingState();
                crossoverScenario.commit({dt,diagnostics:accessController.values().map(access=>access.sharedAxisAppSystem.diagnostics),
                    shape:{coordinates:state.coordinates,positions:state.positions.flatMap(p=>p.map((v,k)=>v+state.origin[k]))},
                    tools:{wire:guidewireTransport.progress,catheter:pigtailCatheter.progress,wireRotation:guidewireRotation,catheterRotation:pigtailCatheter.rotation}});
            }catch(error){crossoverScenario.fail(error.message);}
        }
    }
});

function executeAccumulatedPhysicsStep(idle = false, sliceBudgetMs = null) {
    if (wholeAxisAppSystem && (!loadingAssetsReady() || !endovascularWorld.contactField)) return false;
    if (accessController.switchRequested && !synchronizedStep.pending) return false;
    try {
        const result = synchronizedStep.attempt(fixedDt, sliceBudgetMs);
        if (result.accepted && idle) simulationIdleExecutedSteps++;
        return result.accepted;
    } catch (error) {
        console.error('Shared simulation clock stopped', error);
        return false;
    }
}

function runIdlePhysicsCatchup(epoch = synchronizedStep.epoch, scheduled = true) {
    // A worker message is already a new browser task. Use the remaining idle
    // budget directly instead of adding another timer between physical steps.
    // Preserve the pending timer flag when entering from that message.
    if(scheduled)simulationCatchupPending = false;
    if (epoch !== synchronizedStep.epoch || document.visibilityState !== 'visible') return;
    const deadline = (lastRenderTime ?? performance.now()) + TARGET_RENDER_FRAME_MS;
    runPhysicsIdleBudget({deadline,now:()=>performance.now(),guardMs:PHYSICS_IDLE_GUARD_MS,maxSliceMs:PHYSICS_MAX_SLICE_MS,
        hasDebt:()=>simulationAccumulator+1e-9>=fixedDt,
        canAttempt:()=>synchronizedStep.canAttempt()&&(!accessController.switchRequested||synchronizedStep.pending),
        canFit:room=>room>=(sharedAxisAppSystem?PHYSICS_MIN_SLICE_MS:simulationStepEstimateMs),
        attempt:budget=>executeAccumulatedPhysicsStep(true,budget),maxSlices:MAX_IDLE_PHYSICS_STEPS});
}

function scheduleIdlePhysicsCatchup() {
    if (simulationCatchupPending || !synchronizedStep.canAttempt() ||
        simulationAccumulator + 1e-9 < fixedDt || document.visibilityState !== 'visible') return;
    simulationCatchupPending = true;
    const epoch = synchronizedStep.epoch;
    runtime.timeout(() => runIdlePhysicsCatchup(epoch), 0);
}

function animate(time) {
    if(typeof crossoverAppBenchmark!=='undefined')crossoverAppBenchmark?.recordFrame();
    crossoverScenario?.frame();
    // Render loop: updates geometry, handles fluoroscopy accumulation, and UI
    flushSimulationChanges();
    accessController.applyRequested();
    synchronizedStep.beginFrame();
    const blockedAccess = accessController.values().find(access =>
        accessController.run(access.activeAccessId, () => simulationStepTransaction.blocked));
    if (compositeStatus) {
        const result = endovascularWorld.lastStepResult;
        const progress = result?.diagnostics?.progress;
        const status = (sharedAxisAppSystem
            ? `${sharedAxisAppSystem.diagnostics.projectiveDynamics?'Projective Dynamics':sharedAxisAppSystem.diagnostics.solver==='shared-axis-realtime'?'Kirchhoff — eksperyment 60 Hz':sharedAxisAppSystem.diagnostics.solver==='shared-axis-adaptive'?'Solver adaptacyjny':'Solver referencyjny'} · obliczenia: ${sharedAxisAppSystem.diagnostics.acceptedSteps} · wspólny czas: ${completedSimulationTime.toFixed(2)} s`
            : `Nowy wspólny solver · zaakceptowane kroki: ${endovascularWorld.stepCount}`) +
            (blockedAccess ? ` · ruch odrzucony (${result?.status ?? 'błąd'}) — szczegóły w Debug`
                : result?.status === 'shared-axis-pending' ? ' · obliczanie wspólnego kroku'
                : result?.status === 'computing' ? ` · obliczanie: iteracja ${progress?.directions ?? 0}, ocena ${progress?.evaluations ?? 0}`
                : result?.accepted === false ? ` · wstrzymany: ${result.message || result.status}` : '');
        if (compositeStatus.textContent !== status) compositeStatus.textContent = status;
        for(const button of recoveryButtons)button.disabled=!sharedAxisAppSystem||!blockedAccess;
        const recoveryStatus=document.getElementById('toolMotionRecoveryStatus');
        const recoveries=sharedAxisAppSystem?.diagnostics.recoveries??0;
        recoveryStatus.textContent=synchronizedStep.fault
            ?'Błąd wspólnego kroku. Czas zatrzymany; przeładuj scenę.'
            :blockedAccess
            ?`Wspólny czas zatrzymany: dostęp ${blockedAccess.activeAccessId === 'left' ? 'lewy' : 'prawy'}. Użyj przycisku Wznów ruch.`
            :sharedAxisAppSystem?.diagnostics.recoveryPending?'Sprawdzanie wznowienia z ostatniego poprawnego stanu…'
            :recoveries?'Przywrócono ostatni poprawny stan. Możesz ponownie sterować narzędziami.':'';
    }
    const flowStatus=document.getElementById('bloodFlowMechanicsStatus');
    if(flowStatus){
        const flow=sharedAxisAppSystem?.diagnostics.last?.bloodFlow;
        const text=!sharedAxisAppSystem?'Oddziaływanie wymaga wspólnego solvera.':
            !document.getElementById('bloodFlowCoupling').checked?'Oddziaływanie wyłączone.':
            flow?`Przepływ przy narzędziach: do ${(flow.maxSpeed/10).toFixed(1)} cm/s · odsłonięte ${(flow.exposedLength/10).toFixed(1)} cm`:
            'Przepływ aktywny — narzędzia w koszulce lub krok w trakcie obliczania.';
        if(flowStatus.textContent!==text)flowStatus.textContent=text;
    }
    const frameCpuStartedAt = performance.now();
    const frameMs = lastRenderTime === null ? 0 : time - lastRenderTime;
    const dt = Math.max(0, frameMs / 1000);
    lastRenderTime = time;
    recordBrowserFrame(frameMs);
    if (browserBenchmarkScenario.running) shortCatheterBenchmarkMetrics?.recordFrame(frameMs);
    const compositeReady = !wholeAxisAppSystem || loadingAssetsReady() && !!endovascularWorld.contactField;
    const physicsDt = wholeAxisAppSystem && (!compositeReady || !compositePhysicsClockStarted) ||
        !synchronizedStep.canAttempt() ? 0 : dt;
    if (compositeReady) compositePhysicsClockStarted = true;
    simulationAcceptedTime += physicsDt;
    simulationAccumulator += physicsDt;
    if (simulationAccumulator > simulationPeakBacklog) {
        simulationPeakBacklog = simulationAccumulator;
        if (
            browserBenchmarkScenario.running &&
            !browserBenchmarkScenario.warmingUp
        ) {
            simulationPeakBacklogScenarioMs =
                browserBenchmarkScenario.simulationElapsedMs;
            simulationPeakBacklogElapsedMs =
                performance.now() - browserBenchmarkScenario.startedAt;
            simulationPeakBacklogGuidewireMm = guidewireTransport.progress;
        }
    }
    // Every shared-axis provider is cooperative. Resume its private pending
    // step within the available frame budget, irrespective of solver preset.
    const adaptiveSlices=!!sharedAxisAppSystem;
    const sliceRoom=()=>TARGET_RENDER_FRAME_MS-(performance.now()-frameCpuStartedAt)-
        (adaptiveSlices?simulationRenderReserveMs:PHYSICS_RENDER_RESERVE_MS)-PHYSICS_IDLE_GUARD_MS;
    runPhysicsFrameBudget({
        hasDebt:()=>simulationAccumulator+1e-9>=fixedDt,
        canAttempt:()=>synchronizedStep.canAttempt() && (!accessController.switchRequested || synchronizedStep.pending),
        canFit:()=>sliceRoom()>(adaptiveSlices ? PHYSICS_MIN_SLICE_MS : simulationStepEstimateMs),
        attempt:()=>({accepted:executeAccumulatedPhysicsStep(false,
            Math.max(PHYSICS_MIN_SLICE_MS,Math.min(PHYSICS_MAX_SLICE_MS,sliceRoom()))),
            pending:synchronizedStep.canContinueFrame(adaptiveSlices)}),
        maxSteps:MAX_PHYSICS_STEPS_PER_FRAME,maxSlices:MAX_IDLE_PHYSICS_STEPS,
        resumePending:true
    });
    scheduleIdlePhysicsCatchup();
    const frameSimulationEndedAt = performance.now();
    for(const key of Object.keys(framePresentationMs))framePresentationMs[key]=0;

    if (!synchronizedStep.pending) for (const access of accessController.values()) access.rodNodes.update(access.xpbdWireBody,access.xpbdCatheterBody,!fluoroscopy&&debugLayerVisibility.rodNodes);
    if(mechanicalMeshOutput) {
        const mesh=sharedAxisAppSystem?.diagnostics.mesh;
        const description=mesh?`${mesh.adaptive?'Adaptacyjna':'Referencyjna'} · ${mesh.nodes} węzłów osi · ${mesh.dofs} niewiadomych · odcinki ${mesh.minSpacing.toFixed(2)}–${mesh.maxSpacing.toFixed(1)} mm${mesh.adaptive?` · próg ${mesh.shapeTolerance.toFixed(2).replace('.',',')} mm · ochrona kontaktów ${mesh.contactMargin.toFixed(2).replace('.',',')} mm · skrócenie łuku ${(100*mesh.maxArcLoss).toFixed(2).replace('.',',')}% · limit odcinka ${mesh.maxAllowedSpacing.toFixed(0)} mm`:''}`:
            sharedAxisAppSystem?'Siatka: inicjalizacja':'Siatka starszego solvera · osobne węzły obu narzędzi';
        if(mechanicalMeshOutput.textContent!==description)mechanicalMeshOutput.textContent=description;
    }

    if(newtonDebugOutput) {
        const diag=sharedAxisAppSystem?.diagnostics;
        const description=diag?.projectiveDynamics?`PD eksperymentalny · ${diag.last?.iterations??0} iteracji · ${diag.last?.factorizations??0} faktoryzacji · błąd długości ${((diag.last?.pd?.maxLengthError??0)*100).toFixed(2)}% · penetracja ${(diag.last?.quality?.maxPenetration??0).toFixed(3)} mm · ${diag.last?.pd?.localGlobalConverged?'zbieżny':'budżet iteracji'} · przybliżone tarcie` :diag?.coupledFrictionNewton?(diag.predictiveNewton?'Newton: predykcja ruchu, kontakty i tarcie (eksperyment)':'Newton: szybsze kontakty i tarcie (eksperyment)'):diag?.modifiedNewton?`Newton eksperymentalny · ostatni krok: ${diag.last?.modifiedAccepted??0}/${diag.last?.modifiedAttempts??0} prób z zachowaną macierzą przyjętych · ${diag.last?.modifiedFallbacks??0} powrotów do pełnej macierzy`:'Newton: dotychczasowa metoda';
        const last=diag?.last;
        const complete=Number.isFinite(last?.cpuMs)?`\nOstatni zakończony krok: ${last.iterations??0} iteracji · ${last.factorizations??0} faktoryzacji · ${(last.fullAssemblies??0)+(last.residualAssemblies??0)} złożeń · CPU solvera ${last.cpuMs.toFixed(1)} ms`+
            `\nRównania ${(last.timings?.assemblyMs??0).toFixed(1)} / układ ${(last.timings?.linearMs??0).toFixed(1)} / tarcie ${(last.timings?.frictionMs??0).toFixed(1)} ms`+
            (last.coupledFrictionFallbacks?` · powroty do metody referencyjnej: ${last.coupledFrictionFallbacks}`:''):'';
        const text=description+(diag?.pruneInactiveWitnesses?' · przerzedzanie kontaktów':'')+complete;
        if(newtonDebugOutput.textContent!==text)newtonDebugOutput.textContent=text;
    }

    // Both waveform samples and their screen cursors use committed time.
    // Drawing remains independent of the solver and never advances physiology.
    monitor.render(completedSimulationTime - monitorPublishedTime);
    monitorPublishedTime = completedSimulationTime;

    guidewireMeshAccumulator += dt;
    if (!synchronizedStep.pending && guidewireMeshAccumulator >= GUIDEWIRE_MESH_UPDATE_INTERVAL) {
        guidewireMeshAccumulator = 0;
        const started=performance.now();
        // Whole-axis meshes are already frozen once at the common commit.
        // Rebuilding them here repeats identical tube sampling between ticks.
        for (const access of accessController.values()) if(!access.wholeAxisAppSystem) {
            accessController.run(access.activeAccessId, updateWireMesh);
            stentGraftSystem.refreshDelivery(access.activeAccessId);
        }
        framePresentationMs.wireMesh+=performance.now()-started;
    }
    contactMarkerAccumulator += dt;
    if (!synchronizedStep.pending && contactMarkerAccumulator >= CONTACT_MARKER_UPDATE_INTERVAL) {
        contactMarkerAccumulator = 0;
        const started=performance.now();sampleGuidewireContactMarkers();framePresentationMs.wallDiagnostics+=performance.now()-started;
    }
    pigtailMeshAccumulator += dt;
    if (!synchronizedStep.pending && pigtailMeshAccumulator >= PIGTAIL_MESH_UPDATE_INTERVAL) {
        pigtailMeshAccumulator = 0;
        const started=performance.now();
        for (const access of accessController.values()) if(!access.wholeAxisAppSystem)access.pigtailCatheter.updateMesh();
        framePresentationMs.catheterMesh+=performance.now()-started;
    }
    const contrastShouldRender = !!contrastSystem && (
        contrastSystem.isInjecting || contrastSystem.hasVisibleContrast()
    );
    if (contrastShouldRender) {
        contrastVolumeRenderer?.setDebugMode(!fluoroscopy);
        contrastVolumeRenderer?.update({reuseUnchanged:true});
    } else if (contrastVolumeRenderer) {
        contrastVolumeRenderer.group.visible = false;
    }

    if (fluoroscopy && voxelGroup.parent !== contrastScene) {
        scene.remove(voxelGroup);
        contrastScene.add(voxelGroup);
    } else if (!fluoroscopy && voxelGroup.parent !== scene) {
        contrastScene.remove(voxelGroup);
        scene.add(voxelGroup);
    }
    vesselGroup.visible = !fluoroscopy;
    sheathFluoroMesh.visible = fluoroscopy;
    stentGraftSystem.setFluoroscopy(fluoroscopy);
    for (const access of accessController.values()) {
        access.pigtailCatheter.tipMarkerMaterial.color.setHex(fluoroscopy ? 0xffffff : 0xffc34d);
    }
    if (wallContactMarkers) wallContactMarkers.visible = !fluoroscopy && debugLayerVisibility.wallContacts;
    if (wallBreachMarkers) wallBreachMarkers.visible = !fluoroscopy && debugLayerVisibility.wallContacts;
    if (wallWorstPointMarker) wallWorstPointMarker.visible = !fluoroscopy && debugLayerVisibility.wallContacts && !!wallWorstPointMarker.userData.hasPoint;
    skeletonModel.visible = fluoroscopy;
    injectionUiAccumulator += dt;
    if (injectionUiAccumulator >= 0.1) {
        injectionUiAccumulator = 0;
        stentGraftControls.refresh();
        const injectionSourceStatus = contrastSystem
            ? contrastSystem.getSourceStatus(ui.getInjectionSource())
            : { valid: false, label: '', reason: 'Loading flow model' };
        ui.setInjectButtonDisabled(!injectionSourceStatus.valid || !!contrastSystem?.isInjecting);
        ui.setStopInjectionDisabled(!contrastSystem?.isInjecting);
        ui.setInjectionSourceStatus(
            injectionSourceStatus.valid,
            contrastSystem?.isInjecting
                ? `Injecting via ${injectionSourceStatus.label}`
                : injectionSourceStatus.reason || `${injectionSourceStatus.label} ready`
        );
        const injectionRequest = ui.getInjectionRequest();
        const injectionPreview = contrastSystem
            ? contrastSystem.isInjecting
                ? {
                    valid: true,
                    source: contrastSystem.injection.source,
                    ...contrastSystem.injection.hydraulics
                }
                : contrastSystem.getInjectionPreview(
                    injectionRequest,
                    injectionSourceStatus
                )
            : {
                valid: false,
                reason: 'Flow model is still loading'
            };
        ui.updateInjectionHydraulics(injectionPreview);
    }
    contrastDiagnosticsAccumulator += dt;
    if (contrastDiagnosticsAccumulator >= 0.25) {
        contrastDiagnosticsAccumulator = 0;
        ui.updateContrastDiagnostics(contrastSystem?.getMetrics?.() || null);
    }
    if (
        dsaRoadmapState.invalidateForGeometryRevision(
            ui.getCArmRevision()
        )
    ) {
        syncDsaRoadmapState();
    }
    if (dsaRoadmapState.cinePlaying) {
        const cineAdvance = dsaRoadmapState.advanceCine();
        if (cineAdvance.changed) syncDsaRoadmapState();
    }
    browserBenchmarkUiAccumulator += dt;
    if (browserBenchmarkUiAccumulator >= 0.25) {
        browserBenchmarkUiAccumulator = 0;
        const scenarioStatus = getBrowserBenchmarkScenarioStatus();
        ui.updateBrowserBenchmarkStatus(
            scenarioStatus,
            scenarioStatus.running ? null : lastBrowserBenchmarkScenarioReport
        );
    }
    const frameUpdateEndedAt = performance.now();
    if (fluoroscopy) {
        updateAutoExposure(dt);
        updateXrayTechniqueReadout();
        const pulseRate = Math.max(1, displayMaterial.uniforms.pulseRate.value || 15);
        const pulseInterval = 1000 / pulseRate;
        const viewRevision = ui.getCArmRevision();
        // Integer physical ticks still accumulate floating-point roundoff.
        // Camera movement must remain visible while a solver is paused.
        const shouldAcquireFluoroFrame = viewRevision !== lastFluoroViewRevision ||
            completedSimulationTime * 1000 - lastFluoroPulseTime + 1e-6 >= pulseInterval;
        if (!shouldAcquireFluoroFrame) {
            renderer.setRenderTarget(null);
            renderer.render(displayScene, postCamera);
            ui.updatePerfStats(dt, {simulation:simulationExecutedSteps}, completedSimulationTime);
            recordBrowserFrameCpu(frameCpuStartedAt, frameSimulationEndedAt, frameUpdateEndedAt);
            runtime.frame(animate);
            return;
        }
        lastFluoroPulseTime = completedSimulationTime * 1000;
        lastFluoroViewRevision = viewRevision;
        fluoroPulseIndex += 1;
        displayMaterial.uniforms.fluoroPulseIndex.value = fluoroPulseIndex;

        // Fluoroscopy path:
        // 1) render front/back depth for legacy thickness/scatter cues
        // 2) render stable bone/contrast/metal masks for attenuation.
        //    The bone pass additively stores entry depth, exit depth, and
        //    angle-corrected cortical shell length, so separated overlapping
        //    bones contribute their actual ray lengths instead of collapsing to
        //    one nearest/farthest interval.
        // 3) render scene to offscreen, accumulate with decay
        // 4) display attenuated fluoroscopy image via display shader
        if (staticAnatomyProjectionChanged()) updateStaticAnatomyProjection();

        // Moving soft tissue is acquired with the X-ray pulse and is therefore
        // included in both live imaging and DSA masks/cine. Bones remain cached.
        renderer.setRenderTarget(softTissueTarget);
        renderer.setClearColor(0x000000, 0);
        renderer.clear();
        renderer.render(patientSoftTissue.scene, camera);
        renderer.setClearColor(0x000000, 1);

        renderer.setRenderTarget(contrastTarget);
        renderer.setClearColor(0x000000, 0);
        renderer.clear();
        renderer.render(contrastScene, camera);
        renderer.setClearColor(0x000000, 1);

        renderer.setRenderTarget(metalTarget);
        renderer.setClearColor(0x000000, 0);
        renderer.clear();
        renderMetalProjection(renderer,scene,camera,{
            wireGroups:accessController.values().map(access=>access.wireGroup),
            graftGroup:stentGraftSystem.group,
            wireMaterial:wireProjectionMaterial,graftMaterial:stentGraftProjectionMaterial
        });
        renderer.setClearColor(0x000000, 1);

        renderer.setRenderTarget(catheterTarget);
        renderer.setClearColor(0x000000, 0);
        renderer.clear();
        renderOnlySceneObject(scene, camera, accessController.values().map(access => access.pigtailCatheter.mesh));
        renderer.setClearColor(0x000000, 1);

        renderer.setRenderTarget(catheterMarkerTarget);
        renderer.setClearColor(0x000000, 0);
        renderer.clear();
        const catheterShaftVisibility = accessController.values().map(access => {
            const shaft = access.pigtailCatheter.shaftMesh, visible = shaft.visible;
            shaft.visible = false;
            return {shaft, visible};
        });
        renderOnlySceneObject(scene, camera, accessController.values().map(access => access.pigtailCatheter.mesh));
        for (const {shaft, visible} of catheterShaftVisibility) shaft.visible = visible;
        renderer.setClearColor(0x000000, 1);

        renderer.setRenderTarget(sheathTarget);
        renderer.setClearColor(0x000000, 0);
        renderer.clear();
        renderOnlySceneObject(scene, camera, sheathFluoroMesh);
        renderer.setClearColor(0x000000, 1);

        renderer.setRenderTarget(offscreenTarget);
        renderer.clear();
        renderOnlySceneObject(scene, camera, sheathFluoroMesh);
        const previousOverlayAutoClear = renderer.autoClear;
        renderer.autoClear = false;
        scene.overrideMaterial = wireProjectionMaterial;
        renderOnlySceneObject(scene, camera, accessController.values().map(access => access.wireGroup));
        scene.overrideMaterial = null;
        renderer.render(contrastScene, camera);
        renderer.autoClear = previousOverlayAutoClear;

        blendMaterial.uniforms.currentFrame.value = offscreenTarget.texture;
        blendMaterial.uniforms.previousFrame.value = previousTarget.texture;

        renderer.setRenderTarget(currentTarget);
        renderer.render(blendScene, postCamera);
        renderer.setRenderTarget(null);

        displayMaterial.uniforms.uTexture.value = currentTarget.texture;
        displayMaterial.uniforms.contrastTexture.value = contrastTarget.texture;
        displayMaterial.uniforms.thicknessTexture.value = thicknessTarget.texture;
        displayMaterial.uniforms.metalTexture.value = metalTarget.texture;
        displayMaterial.uniforms.catheterTexture.value = catheterTarget.texture;
        displayMaterial.uniforms.catheterMarkerTexture.value = catheterMarkerTarget.texture;
        displayMaterial.uniforms.sheathTexture.value = sheathTarget.texture;
        displayMaterial.uniforms.boneTexture.value = boneTarget.texture;
        processDsaRoadmapCapture();
        renderer.setRenderTarget(null);
        renderer.render(displayScene, postCamera);
        completeFirstLoadedFrame();

        // Ping-pong accumulation targets for next frame's persistence
        const temp = previousTarget;
        previousTarget = currentTarget;
        currentTarget = temp;
    } else {
        lastFluoroPulseTime = -Infinity;
        updateXrayTechniqueReadout();
        renderer.setRenderTarget(null);
        if (debugVesselSurface?.mesh.visible) debugVesselSurface.prepare(renderer, camera);
        if (contrastVolumeRenderer) contrastVolumeRenderer.renderDebug(renderer, scene, camera);
        else renderer.render(scene, camera);
        if (debugLayerVisibility.vesselLabels) anatomyLabelRenderer.render(scene, camera);
        completeFirstLoadedFrame();
    }

    ui.updatePerfStats(dt, {simulation:simulationExecutedSteps}, completedSimulationTime);
    recordBrowserFrameCpu(frameCpuStartedAt, frameSimulationEndedAt, frameUpdateEndedAt);

    runtime.frame(animate);
}
